    /**
     * 设置所有超时时间
     * @param {number} connectSeconds 连接超时时间（秒）
     * @param {number} readSeconds 读取超时时间（秒）
     * @param {number} writeSeconds 写入超时时间（秒）
     * @see {@link https://doc.deeke.cn/base/http/http.html#settimeoutconnectsecondsreadsecondswriteseconds DeekeScript 文档}
     */
    setTimeout(connectSeconds: number, readSeconds: number, writeSeconds: number): void;
