/**
 * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html DeekeScript 文档}
 */
interface socketIoClient {
    /**
     * 获取socketIoClient实例
     * @param {string} serverUrl socketIOServer地址
     * @param {boolean} reconnect 是否自动重连（默认为true）
     * @param {number} timeout 重连超时时间（毫秒）（默认为5000毫秒）
     * @returns {socketIoClient} socketIoClient
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#getinstanceserverurlreconnecttimeout DeekeScript 文档}
     */
    getInstance(serverUrl: string, reconnect: boolean, timeout: number): socketIoClient;
    /**
     * 连接socketIOServer
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#connect DeekeScript 文档}
     */
    connect(): void;
    /**
     * 断开socketIOServer
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#disconnect DeekeScript 文档}
     */
    disconnect(): void;
    /**
     * 是否已连接
     * @returns {boolean} boolean
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#isconnected DeekeScript 文档}
     */
    isConnected(): boolean;
    /**
     * 向服务器发送事件和数据
     * @param {string} eventName 事件名称
     * @param {string} data 数据
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#emiteventnamedata DeekeScript 文档}
     */
    emit(eventName: string, data: string): void;
    /**
     * 向服务器发送事件和数据
     * @param {string} eventName 事件名称
     * @param {string} data 数据
     * @param {function} callback 服务器确认后的回调函数
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#emiteventnamedatacallback DeekeScript 文档}
     */
    emit(eventName: string, data: string, callback: function): void;
    /**
     * 监听事件
     * @param {string} eventName eventName
     * @param {(data: string) => void} callback callback
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#oneventnamecallback DeekeScript 文档}
     */
    on(eventName: string, callback: (data: string) => void): void;
    /**
     * 移除事件监听器
     * @param {string} eventName eventName
     * @param {(data: string) => void} callback callback
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#offeventnamecallback DeekeScript 文档}
     */
    off(eventName: string, callback: (data: string) => void): void;
    /**
     * 移除事件监听器
     * @param {string} eventName eventName
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#offeventname DeekeScript 文档}
     */
    off(eventName: string): void;
    /**
     * 移除所有事件监听器
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#off DeekeScript 文档}
     */
    off(): void;
    /**
     * 重置当前实例的是否重连
     * @param {boolean} bool 是否自动重连
     * @see {@link https://doc.deeke.cn/base/socketIoClient/socketIoClient.html#setreconnectbool DeekeScript 文档}
     */
    setReconnect(bool: boolean): void;
}

